@media(max-width:580px){.sidebar{inset:auto 0 0;width:auto;height:57px;z-index:15;flex-direction:row;padding:5px 9px;background:#15161a;border-right:0;border-top:1px solid #34343b}.brand{display:none}.main-nav{width:100%;display:grid;grid-template-columns:repeat(3,1fr);margin:0;gap:3px}.nav-item{height:46px;display:flex;flex-direction:column;gap:1px;font-size:8px}.nav-item>span:not(.nav-icon){display:block}.nav-item .nav-icon{font-size:16px;line-height:19px}.nav-arrow{display:none!important}.main-content{margin:0 0 57px;width:100%;padding:0 14px}.topbar{height:54px}.breadcrumb{font-size:8px}.topbar-right{gap:9px}.resource-pill{height:26px;padding:0 7px;gap:5px}.resource-label{font-size:7px}.view{padding-top:25px}.page-heading{align-items:flex-start;margin-bottom:20px}.page-heading h1{font-size:34px}.heading-copy{max-width:265px;font-size:11px;line-height:1.5}.trial-status{font-size:7px;padding:7px;margin-top:22px;white-space:nowrap}.battle-layout{gap:12px}.arena{height:260px;padding:12px}.combatants{grid-template-columns:1fr 27px 1fr;gap:3px}.combatant{padding:8px 7px}.combatant-name{gap:6px}.combatant-name strong{font-size:9px}.combatant-name .eyebrow{font-size:6px}.faction-mark,.enemy-icon{width:22px;height:22px}.enemy-intent{margin-left:27px;font-size:8px}.health-row{gap:4px}.health-value{font-size:7px}.arena-art{width:180px}.versus{font-size:8px}.hand{grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.battle-card{height:133px;padding:7px 5px}.card-cost{width:17px;height:17px;font-size:9px}.card-glyph{font-size:15px}.card-name{font-size:9px;min-height:21px}.card-type{font-size:6px;letter-spacing:.4px}.card-desc{font-size:7px;line-height:1.3}.roster-list{grid-template-columns:1fr}.roster-unit{grid-template-columns:40px 1fr 27px}.roster-panel{padding:13px}.strategy-tip{margin-top:12px}.training-card{grid-template-columns:52px minmax(0,1fr);gap:10px}.training-card .demon-portrait{width:49px;height:49px}.train-action{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;text-align:left;padding-top:9px;border-top:1px solid #343138}.train-action .level-label{margin:0}.train-button{padding:9px}.training-info h3{font-size:14px}.training-info p{font-size:9px}.codex-grid{grid-template-columns:1fr}.codex-card{min-height:245px}.codex-foot{flex-wrap:wrap}.codex-foot .text-link{margin-left:0;width:100%}.page-footer{font-size:7px;margin-top:21px}.page-footer span:last-child{display:none}}

const DEMONS = [
  {id:'kairo',name:'Kairo',title:'Cinderling',glyph:'♨',kind:'EMBER',color:'#f08b6e',glow:'#bd5139',maxHp:42,ability:'Cinder Rush',description:'Deal 8 damage. If your ward is active, deal 3 more.',lore:'A spark that refused to die. Kairo turns careful defense into a sudden blaze.',cards:[['Cinder Jab','STRIKE','Deal 6 damage.','✦',1],['Flare Burst','STRIKE','Deal 10 damage.','✺',2],['Ashen Guard','WARD','Gain 8 ward.','⬡',1],['Kindle','FOCUS','Restore 7 vitality.','✧',2],['Cinder Rush','SIGNATURE','Deal 8 damage. +3 if warded.','♨',2]]},
  {id:'morrow',name:'Morrow',title:'Gloam Hound',glyph:'◉',kind:'SHADE',color:'#b88bd1',glow:'#744791',maxHp:37,ability:'Nightfall',description:'Deal 7 damage and gain 4 ward.',lore:'A patient hunter from the space between heartbeats. Morrow rewards the master who waits.',cards:[['Umbral Bite','STRIKE','Deal 7 damage.','☾',1],['Shadow Pounce','STRIKE','Deal 12 damage.','⌁',2],['Veil Step','WARD','Gain 10 ward.','◌',1],['Siphon','FOCUS','Restore 6 vitality.','◈',2],['Nightfall','SIGNATURE','Deal 7 damage. Gain 4 ward.','◉',2]]},
  {id:'bront',name:'Bront',title:'Stone Warden',glyph:'⬟',kind:'TITAN',color:'#cfb277',glow:'#8e673a',maxHp:52,ability:'Faultline',description:'Deal 6 damage and gain 8 ward.',lore:'Older than the first fortress. Bront teaches that an unbroken will is its own weapon.',cards:[['Knuckle Stone','STRIKE','Deal 6 damage.','⬟',1],['Faultline','STRIKE','Deal 9 damage.','⌑',2],['Granite Skin','WARD','Gain 12 ward.','⬡',1],['Stillness','FOCUS','Restore 8 vitality.','◌',2],['Faultline','SIGNATURE','Deal 6 damage. Gain 8 ward.','⛰',2]]}
];
const ENEMIES=[
 {name:'Hollow Wisp',icon:'◉',hp:38,damage:6,phrase:'Gathers a spiteful spark',color:'#aa7c9c'},
 {name:'Rift Stalker',icon:'⌁',hp:49,damage:8,phrase:'Winds up a rift slash',color:'#c17b78'},
 {name:'The Ashen Judge',icon:'♜',hp:66,damage:10,phrase:'Raises its execution brand',color:'#d18e62'}
];
const defaults={essence:0,masterLevel:1,wins:0,losses:0,training:{kairo:1,morrow:1,bront:1},custom:[],selected:'kairo',unlocked:1};
let state=loadState();let battle=null;let toastTimer;
function loadState(){try{const saved=JSON.parse(localStorage.getItem('veilbound-save'));if(saved)return {...defaults,...saved,training:{...defaults.training,...saved.training},custom:saved.custom||[]}}catch(e){}return structuredClone(defaults)}
function save(){localStorage.setItem('veilbound-save',JSON.stringify(state));renderHeader()}
function allDemons(){return [...DEMONS,...state.custom]}
function demonById(id){return allDemons().find(d=>d.id===id)||DEMONS[0]}
function maxHp(d){return d.maxHp+(Math.max(1,state.training[d.id]||1)-1)*5}
function renderHeader(){document.getElementById('essence-count').textContent=state.essence;document.getElementById('training-essence').textContent=`${state.essence} ESSENCE`;document.getElementById('master-level').textContent=`${masterTitle()} · Lv. ${state.masterLevel}`;document.getElementById('trial-label').textContent=`TRIAL ${String(Math.min(state.wins+1,3)).padStart(2,'0')} / 03`}
function masterTitle(){return state.wins>=3?'Demon Master':state.wins>=2?'Adept':state.wins>=1?'Binder':'Novice'}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function switchView(view){document.querySelectorAll('.view').forEach(el=>el.classList.remove('active-view'));document.getElementById(`view-${view}`).classList.add('active-view');document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const titles={battle:'TRIAL GROUNDS',training:'TRAINING HALL',codex:'DEMON CODEX'};document.getElementById('page-crumb').textContent=titles[view];if(view==='training')renderTraining();if(view==='codex')renderCodex();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));
function renderRoster(){const list=document.getElementById('roster-list');list.innerHTML=allDemons().map(d=>{const level=state.training[d.id]||1;return `<button class="roster-unit ${state.selected===d.id?'selected':''}" data-select-demon="${d.id}" style="--demon-color:${d.color};--demon-glow:${d.glow}"><span class="demon-portrait">${d.glyph}</span><span class="roster-info"><strong>${escapeHtml(d.name)}, ${escapeHtml(d.title)}</strong><span>${d.kind} · ${maxHp(d)} VIT</span><i class="mini-xp"><span style="width:${Math.min(100,(level-1)*34)}%"></span></i></span><span class="level-pill">LV.${level}</span>${state.selected===d.id?'<span class="active-ribbon">BOUND</span>':''}</button>`}).join('');list.querySelectorAll('[data-select-demon]').forEach(btn=>btn.addEventListener('click',()=>{if(battle?.active){showToast('Finish the trial before changing your bound.');return}state.selected=btn.dataset.selectDemon;save();renderRoster();renderBattleReady()}))}
function renderBattleReady(){if(battle?.active)return;const d=demonById(state.selected);document.getElementById('active-demon-name').textContent=`${d.name}, ${d.title}`;document.getElementById('player-health-text').textContent=`${maxHp(d)} / ${maxHp(d)}`;document.getElementById('player-health-bar').style.width='100%';document.getElementById('enemy-name').textContent=ENEMIES[Math.min(state.wins,2)].name;document.getElementById('enemy-icon').textContent=ENEMIES[Math.min(state.wins,2)].icon;document.getElementById('enemy-health-text').textContent=`${ENEMIES[Math.min(state.wins,2)].hp} / ${ENEMIES[Math.min(state.wins,2)].hp}`;document.getElementById('enemy-health-bar').style.width='100%';document.getElementById('enemy-intent').innerHTML='<span class="intent-icon">⌁</span><span>Waiting for you</span>';document.getElementById('round-label').textContent='READY';document.getElementById('turn-marker').textContent='YOUR TURN';document.getElementById('battle-hint').textContent='Select your opening move';document.getElementById('player-status').textContent='';document.getElementById('energy-count').textContent='3';document.getElementById('energy-pips').innerHTML='<i class="filled"></i><i class="filled"></i><i class="filled"></i>';document.getElementById('end-turn').disabled=true;document.getElementById('hand-instruction').textContent='Choose cards to shape the fight';document.getElementById('hand').innerHTML='';}
function startBattle(){if(battle?.active)return;const d=demonById(state.selected),e=ENEMIES[Math.min(state.wins,2)];battle={active:true,round:1,playerHp:maxHp(d),maxPlayerHp:maxHp(d),ward:0,enemyHp:e.hp,maxEnemyHp:e.hp,energy:3,used:[],enemy:e,playerBurn:0};document.getElementById('active-demon-name').textContent=`${d.name}, ${d.title}`;document.getElementById('enemy-name').textContent=e.name;document.getElementById('enemy-icon').textContent=e.icon;document.getElementById('round-label').textContent='ROUND 01';document.getElementById('battle-hint').textContent='The enemy is preparing an attack';document.getElementById('turn-marker').textContent='YOUR TURN';document.getElementById('end-turn').disabled=false;renderHand();updateBattleUI();showToast(`${d.name} answers your call.`)}
function renderHand(){const d=demonById(state.selected),hand=document.getElementById('hand');hand.innerHTML=d.cards.map((card,i)=>{const [name,type,desc,glyph,cost]=card;let disabled=!battle?.active||battle.energy<cost||battle.used.includes(i);return `<button class="battle-card" data-card="${i}" style="--card-color:${d.color}" ${disabled?'disabled':''}><span class="card-top"><span class="card-cost">${cost}</span><span class="card-glyph">${glyph}</span></span><span class="card-name">${escapeHtml(name)}</span><span class="card-type">${type}</span><span class="card-desc">${desc}</span></button>`}).join('');document.getElementById('card-count').textContent=`${d.cards.length} CARDS`;hand.querySelectorAll('[data-card]').forEach(el=>el.addEventListener('click',()=>playCard(Number(el.dataset.card),el)))}
function playCard(index,el){if(!battle?.active)return;const d=demonById(state.selected),card=d.cards[index],cost=card[4];if(battle.energy<cost||battle.used.includes(index))return;const name=card[0];battle.energy-=cost;battle.used.push(index);el.classList.add('played');const signature=index===4;if(signature){if(d.id==='kairo'){let damage=8+(battle.ward>0?3:0);damageEnemy(damage)}else if(d.id==='morrow'){damageEnemy(7);battle.ward+=4}else if(d.id==='bront'){damageEnemy(6);battle.ward+=8}else{damageEnemy(8);battle.ward+=4}}else if(index===0){damageEnemy(d.id==='morrow'?7:d.id==='bront'?6:6)}else if(index===1){damageEnemy(d.id==='morrow'?12:d.id==='bront'?9:10)}else if(index===2){battle.ward+=d.id==='bront'?12:d.id==='morrow'?10:8;showToast(`Ward raised to ${battle.ward}.`)}else if(index===3){let heal=d.id==='bront'?8:d.id==='kairo'?7:6;battle.playerHp=Math.min(battle.maxPlayerHp,battle.playerHp+heal);showToast(`Restored ${heal} vitality.`)}if(battle.enemyHp<=0){renderHand();updateBattleUI();finishBattle(true);return}renderHand();updateBattleUI();if(battle.energy===0||battle.used.length>=d.cards.length)document.getElementById('end-turn').disabled=false;else document.getElementById('end-turn').disabled=false}
function damageEnemy(amount){if(!battle)return;battle.enemyHp=Math.max(0,battle.enemyHp-amount);floatText(document.querySelector('.enemy-combatant'),`−${amount}`);document.getElementById('arena').classList.remove('shake');void document.getElementById('arena').offsetWidth;document.getElementById('arena').classList.add('shake')}
function floatText(parent,text){if(!parent)return;const node=document.createElement('span');node.className='floating-damage';node.textContent=text;node.style.left=`${50+Math.random()*18-9}%`;node.style.top='30%';parent.appendChild(node);setTimeout(()=>node.remove(),850)}
function updateBattleUI(){if(!battle)return;const p=Math.max(0,battle.playerHp);document.getElementById('player-health-text').textContent=`${p} / ${battle.maxPlayerHp}`;document.getElementById('player-health-bar').style.width=`${p/battle.maxPlayerHp*100}%`;document.getElementById('enemy-health-text').textContent=`${battle.enemyHp} / ${battle.maxEnemyHp}`;document.getElementById('enemy-health-bar').style.width=`${battle.enemyHp/battle.maxEnemyHp*100}%`;document.getElementById('energy-count').textContent=battle.energy;document.getElementById('energy-pips').innerHTML=[0,1,2].map(n=>`<i class="${n<battle.energy?'filled':''}"></i>`).join('');document.getElementById('player-status').textContent=battle.ward?`WARD ${battle.ward}`:'';document.getElementById('enemy-intent').innerHTML=`<span class="intent-icon">⚡</span><span>${battle.enemy.phrase} · ${battle.enemy.damage}</span>`;document.getElementById('round-label').textContent=`ROUND ${String(battle.round).padStart(2,'0')}`}
function endTurn(){if(!battle?.active)return;let attack=battle.enemy.damage;if(battle.ward){const absorbed=Math.min(attack,battle.ward);attack-=absorbed;battle.ward-=absorbed;if(absorbed)showToast(`Ward absorbed ${absorbed} damage.`)}battle.playerHp=Math.max(0,battle.playerHp-attack);if(attack){floatText(document.querySelector('.player-combatant'),`−${attack}`);document.getElementById('arena').classList.add('shake')}if(battle.playerHp<=0){updateBattleUI();finishBattle(false);return}battle.round++;battle.energy=3;battle.used=[];document.getElementById('end-turn').disabled=false;document.getElementById('battle-hint').textContent='Your resolve is renewed';renderHand();updateBattleUI()}
function finishBattle(won){if(!battle)return;battle.active=false;document.getElementById('end-turn').disabled=true;const d=demonById(state.selected);let reward=won?2+Math.min(state.wins,2):1;if(won){state.wins++;state.essence+=reward;state.masterLevel=Math.min(10,1+Math.floor(state.wins/2));state.unlocked=Math.min(3,Math.max(state.unlocked,state.wins+1));state.training[d.id]=(state.training[d.id]||1)+1;save();renderRoster();document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="result-modal"><div class="result-symbol">✦</div><span class="eyebrow">A BOND DEEPENS</span><h2>${state.wins>=3?'Demon Master.':'Trial conquered.'}</h2><p>${d.name} grew stronger through your strategy. The next trial will not be so forgiving.</p><div class="reward-line">+${reward} ESSENCE &nbsp;·&nbsp; ${d.name.toUpperCase()} REACHED LV.${state.training[d.id]}</div><button class="modal-button" id="result-continue">${state.wins>=3?'CLAIM YOUR TITLE':'CONTINUE THE TRIAL'} →</button></div></div>`;document.getElementById('result-continue').onclick=()=>{document.getElementById('modal-root').innerHTML='';renderBattleReady();renderRoster();if(state.wins>=3){showToast('You have earned the title of Demon Master. Replay the final trial to keep growing.')}}}else{state.losses++;state.essence+=reward;save();document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="result-modal"><div class="result-symbol">⌁</div><span class="eyebrow">A LESSON, NOT AN ENDING</span><h2>Regroup and return.</h2><p>The veil does not forgive a careless master. Train your demon and read the intent next time.</p><div class="reward-line">+${reward} ESSENCE &nbsp;·&nbsp; LOSS IS A TEACHER</div><button class="modal-button" id="result-continue">RETURN TO THE TRIAL →</button></div></div>`;document.getElementById('result-continue').onclick=()=>{document.getElementById('modal-root').innerHTML='';renderBattleReady();renderRoster()}}renderHeader();renderHand()}
document.getElementById('end-turn').addEventListener('click',endTurn);
function renderTraining(){const root=document.getElementById('training-roster');root.innerHTML=allDemons().map(d=>{const level=state.training[d.id]||1,cost=level*3;return `<article class="training-card ${state.selected===d.id?'active-training':''}" style="--demon-color:${d.color};--demon-glow:${d.glow}"><div class="demon-portrait">${d.glyph}</div><div class="training-info"><h3>${escapeHtml(d.name)} · ${escapeHtml(d.title)}</h3><span class="subname">${d.kind} DEMON &nbsp;·&nbsp; ${d.ability}</span><p>${escapeHtml(d.lore)}</p><div class="training-stats"><span>VIT <b>${maxHp(d)}</b></span><span>LEVEL <b>${level}</b></span><span>${level>=3?'SIGNATURE AWAKENED':'NEXT · +5 VIT'}</span></div></div><div class="train-action"><span class="level-label">NEXT RANK · ${cost} ✧</span><button class="train-button" data-train="${d.id}" ${state.essence<cost?'disabled':''}>TRAIN DEMON <span>−${cost} ✧</span></button></div></article>`}).join('');root.querySelectorAll('[data-train]').forEach(button=>button.addEventListener('click',()=>{let id=button.dataset.train,level=state.training[id]||1,cost=level*3;if(state.essence<cost)return;state.essence-=cost;state.training[id]=level+1;save();renderTraining();renderRoster();renderBattleReady();showToast(`${demonById(id).name} reached level ${level+1}.`)}))}
function renderCodex(){const root=document.getElementById('codex-grid');root.innerHTML=allDemons().map((d,i)=>`<article class="codex-card" style="--demon-color:${d.color};--demon-glow:${d.glow}"><div class="codex-top"><span class="codex-index">NO. ${String(i+1).padStart(2,'0')} &nbsp;·&nbsp; LV.${state.training[d.id]||1}</span><span class="codex-class">${escapeHtml(d.kind)}</span></div><div class="codex-emblem">${d.glyph}</div><h2>${escapeHtml(d.name)}</h2><span class="codex-sub">${escapeHtml(d.title)} · ${maxHp(d)} VIT</span><p>${escapeHtml(d.lore)}</p><div class="signature">SIGNATURE · ${escapeHtml(d.ability)}<span>${escapeHtml(d.description)}</span></div></article>`).join('')+`<article class="codex-card create-card"><div class="codex-top"><span class="codex-index">YOUR CREATION</span><span class="codex-class">CUSTOM BOND</span></div><div class="codex-emblem" style="color:#d69075">＋</div><h2>Bind a new demon</h2><span class="codex-sub">MAKE THE CODEX YOURS</span><p>Give your demon a name, a nature, and a signature ability. Add your own creations to your coven.</p><button class="train-button" id="create-demon">＋ &nbsp; CREATE A DEMON</button></article>`;document.getElementById('create-demon').addEventListener('click',openCreateModal)}
function openCreateModal(){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><form class="result-modal create-form" id="create-form"><div class="result-symbol">✧</div><span class="eyebrow">A SOUL TAKES SHAPE</span><h2>Bind your demon.</h2><p>Design a new member of your coven. They'll enter the next trial at level 1.</p><label class="form-label">DEMON NAME<input name="name" maxlength="18" required placeholder="e.g. Vesper" /></label><label class="form-label">TITLE<input name="title" maxlength="22" required placeholder="e.g. The Star Eater" /></label><label class="form-label">NATURE<select name="kind"><option>FROST</option><option>STORM</option><option>VOID</option><option>BEAST</option><option>SPIRIT</option><option>OTHER</option></select></label><label class="form-label">SIGNATURE ABILITY<input name="ability" maxlength="24" required placeholder="e.g. Starfall" /></label><label class="form-label">WHAT IT DOES<input name="description" maxlength="72" required placeholder="Describe your demon's signature" /></label><div class="form-actions"><button type="button" class="cancel-button" id="cancel-create">CANCEL</button><button type="submit" class="modal-button">BIND TO COVEN →</button></div></form></div>`;document.getElementById('cancel-create').onclick=()=>document.getElementById('modal-root').innerHTML='';document.getElementById('create-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const id='custom-'+Date.now();const demon={id,name:String(data.get('name')).trim(),title:String(data.get('title')).trim(),kind:String(data.get('kind')),glyph:['✺','☽','♜','◇','♧'][state.custom.length%5],color:['#8bc2bc','#b397d4','#d29175','#8faad0'][state.custom.length%4],glow:'#684a70',maxHp:40,ability:String(data.get('ability')).trim(),description:String(data.get('description')).trim(),lore:`A demon of ${String(data.get('kind')).toLowerCase()}, bound by your imagination. Its true nature will be revealed through training.`,cards:[[`${data.get('ability')}`,'STRIKE','Deal 6 damage.','✦',1],['Rending Blow','STRIKE','Deal 10 damage.','✺',2],['Demon Ward','WARD','Gain 9 ward.','⬡',1],['Soul Mend','FOCUS','Restore 7 vitality.','✧',2],[String(data.get('ability')),'SIGNATURE','Deal 8 damage. Gain 4 ward.','◈',2]]};state.custom.push(demon);state.training[id]=1;state.selected=id;save();document.getElementById('modal-root').innerHTML='';renderCodex();renderRoster();showToast(`${demon.name} is bound to your coven.`)});}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
// Start the first battle from the arena, and offer replay after the three trials.
document.getElementById('arena').addEventListener('click',()=>{if(!battle?.active){startBattle()}});
document.getElementById('battle-hint').addEventListener('click',()=>{if(!battle?.active)startBattle()});
// Add clear, always-visible start controls to the arena footer.
document.getElementById('battle-hint').textContent='Tap the arena to begin your trial';
renderHeader();renderRoster();renderBattleReady();

