const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002');await page.evaluate(()=>localStorage.removeItem('veilbound-save'));await page.reload();
 await page.locator('#battle-hint').click();
 for(let victory=0;victory<3;victory++){
   let turns=0;
   while(await page.locator('#modal-root .result-modal').count()===0&&turns<25){
     const available=page.locator('.battle-card:not(:disabled)');
     if(await available.count())await available.first().click();else await page.locator('#end-turn').click();
     turns++;
   }
   if(!(await page.locator('#modal-root .result-modal').count()))throw new Error(`trial ${victory+1} stalled`);
   console.log(`Trial ${victory+1}: ${await page.locator('.result-modal h2').textContent()}`);
   await page.locator('#result-continue').click();
 }
 const sigType=await page.locator('.battle-card[data-card="4"] .card-type').textContent();
 const master=await page.locator('#master-level').textContent();
 await page.screenshot({path:'/tmp/opencode/game-latest.jpg',type:'jpeg',quality:78});
 console.log(JSON.stringify({signature:sigType,master,errors},null,2));await browser.close();
})();
